import { lessonNames } from './paths.js';
import { advancedTracks, advancedRows } from './advanced-curriculum.js';

// Original StudentOS instruction and exercises. Links are optional further reading.
const sources = {
  javascript: 'https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide',
  react: 'https://react.dev/learn',
  sql: 'https://www.postgresql.org/docs/current/tutorial.html',
  python: 'https://docs.python.org/3/tutorial/',
  devops: 'https://docs.docker.com/get-started/',
  dsa: 'https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-fall-2011/'
};
// Each row: objective, instruction, worked example, question, choices, answer, explanation.
const rows = {
  javascript: [['Distinguish values from their display.', 'A value has a type that affects its operations. A score is usually a number; a student identifier is usually text even when it contains digits. Inspect the value before converting it.', 'const score = 80;\nconst id = "0080";\nconsole.log(typeof score, typeof id);', 'Which types are printed?', ['number, string', 'string, number', 'number, number'], 0, '80 is numeric; quotation marks preserve the identifier as text, including its leading zeros.'], ['Choose const or let deliberately.', 'Use const for bindings that will not be reassigned and let when a new value must replace the binding. A const object can still have mutable properties; const does not freeze its contents.', 'const student = { year: 1 };\nstudent.year = 2;', 'What happens?', ['A syntax error', 'student.year becomes 2', 'The object is automatically frozen'], 1, 'The binding still refers to the same object. Its year property can change.'], ['Avoid accidental string concatenation.', 'User input often arrives as text. Convert a numeric input explicitly and check that the result is finite. The + operator joins text when an operand is a string.', 'const amount = "20";\nconsole.log(amount + 5);\nconsole.log(Number(amount) + 5);', 'What is printed?', ['25 and 25', '205 and 25', '205 and 205'], 1, 'The first expression concatenates; Number converts the second expression to numeric addition.'], ['Express a decision with a boundary.', 'A condition selects which branch executes. Name the boundary and test the value exactly at it. A passing mark of 50 includes 50, so the comparison must be greater than or equal.', 'const score = 50;\nconst passed = score >= 50;', 'Is passed true?', ['Yes', 'No', 'Only for scores greater than 50'], 0, 'The >= comparison includes the boundary value 50.'], ['Trace a loop without skipping its boundaries.', 'A loop repeats while its condition stays true. Write the starting value, the condition and the update separately when tracing. An index less than length visits valid array positions.', 'let total = 0;\nfor (let i = 0; i < 3; i++) total += i;', 'What is total?', ['6', '3', '2'], 1, 'The visited values are 0, 1 and 2. Their sum is 3.'], ['Separate a function from its invocation.', 'A function packages behavior. Defining it does not run it; calling it supplies arguments. Use a small function when the same rule should be applied consistently in several places.', 'function double(value) { return value * 2; }\nconst result = double(7);', 'What is result?', ['14', '7', 'undefined'], 0, 'Calling double with 7 returns twice that input.'], ['Return a useful value to the caller.', 'Logging helps inspection, but a caller receives the return value. A function with no return statement yields undefined. Separate calculation from display so the calculation can be tested.', 'function add(a, b) { const sum = a + b; }\nconst result = add(2, 3);', 'What is result?', ['5', 'undefined', '0'], 1, 'The sum is calculated locally, but never returned.'], ['Read array positions and length correctly.', 'Arrays are ordered and zero-indexed. The first element is at index zero, and the last valid index is length minus one. Reading an absent index yields undefined.', 'const topics = ["SQL", "DSA", "React"];\nconsole.log(topics[1]);', 'What is printed?', ['SQL', 'DSA', 'React'], 1, 'Index one refers to the second array element.'], ['Transform an array without replacing the original values.', 'map calls a transformation for each element and returns a new array. Return the transformed value from the callback. It is useful for turning records into display labels.', 'const scores = [1, 2, 3];\nconst doubled = scores.map(n => n * 2);', 'What is doubled?', ['[2, 4, 6]', '[1, 2, 3]', '6'], 0, 'Each element produces a new doubled element in the resulting array.'], ['Keep elements using a predicate.', 'filter retains elements for which the callback returns a truthy value. It does not change those elements. Use it to express inclusion rules, then handle the empty result.', 'const scores = [40, 50, 70];\nconst passed = scores.filter(n => n >= 50);', 'What is passed?', ['[70]', '[50, 70]', '[40]'], 1, 'Both 50 and 70 satisfy the inclusive passing condition.'], ['Distinguish object fields from variable names.', 'An object groups named values. Dot notation reads a known property; bracket notation uses a computed key. A missing property produces undefined, so validate required fields at boundaries.', 'const student = { name: "Mira", year: 2 };\nconst key = "year";\nconsole.log(student[key]);', 'What is printed?', ['year', '2', 'undefined'], 1, 'Bracket notation reads the property whose name is held in key.'], ['Trace names through lexical scope.', 'A function can read variables from the scope where it was defined. Inner bindings can shadow outer names without changing the outer value. Avoid reusing a name when it hides important context.', 'const year = 1;\nfunction readYear() { const year = 3; return year; }\nconsole.log(readYear(), year);', 'Which pair is printed?', ['3, 3', '1, 1', '3, 1'], 2, 'The inner binding is separate from the outer binding.'], ['Explain a closure through a retained variable.', 'A returned function can retain access to variables from its defining call. Different calls create separate retained environments. This is useful for private counters and configurable callbacks.', 'function counter() { let n = 0; return () => ++n; }\nconst next = counter();\nnext();\nconsole.log(next());', 'What is printed?', ['1', '2', '0'], 1, 'Both invocations update the same retained n for this counter instance.'], ['Treat a promise as a future result.', 'A promise represents completion or failure of an asynchronous operation. A then handler receives the fulfilled value. Returning a value from a handler passes it to the next handler.', 'Promise.resolve(3).then(n => n + 2).then(console.log);', 'What value reaches console.log?', ['3', '5', 'undefined'], 1, 'The first handler returns 5, so the next handler receives 5.'], ['Await a result and preserve asynchronous control flow.', 'await pauses the surrounding async function until its promise settles. Other work can continue while the function waits. An async function itself always returns a promise.', 'async function value() { return 7; }\nconst answer = await value();', 'What is answer?', ['A function', '7', 'undefined'], 1, 'Awaiting the promise returned by value obtains its fulfilled value.'], ['Handle a rejected operation where recovery is possible.', 'Errors from awaited promises can be caught with try/catch. A useful handler shows an actionable state and preserves retry information. Silently swallowing an error makes a failure look like success.', 'async function load() {\n try { await Promise.reject(new Error("offline")); }\n catch { return "retry"; }\n}', 'What does awaiting load() return?', ['retry', 'offline', 'It cannot return'], 0, 'The rejection is caught and the catch block returns the recovery value.'], ['Pass an event handler rather than calling it during setup.', 'An event listener expects a function to call when the event occurs. Passing a function reference delays work. Calling the function while attaching the listener performs work immediately.', 'button.addEventListener("click", save);', 'When is save called by this listener?', ['During attachment', 'When the click occurs', 'At every page refresh only'], 1, 'The function reference is registered for a later click event.'], ['Compose calculation, validation and rendering.', 'A tiny application is easier to maintain when input validation, data changes and rendering have clear responsibilities. Start with a useful flow and test the empty input and duplicate action before adding features.', 'const names = ["Mira"];\nfunction addName(name) {\n if (!name.trim() || names.includes(name)) return false;\n names.push(name); return true;\n}', 'What does addName("Mira") return?', ['true', 'false', 'undefined'], 1, 'The duplicate guard prevents adding a second identical entry.']],
  react: [['Choose component boundaries around responsibilities.', 'Break a page into parts that have clear inputs and jobs. A repeated event card is a useful component; a single punctuation mark usually is not. Keep a shared data owner above components that must coordinate.', 'Page → EventList → EventCard', 'Where should a list-wide filter usually live?', ['Inside every card independently', 'In the owner of the filtered list', 'In CSS only'], 1, 'The list owner can calculate a consistent filtered result for every card.'], ['Return markup from a capitalized component.', 'A function component describes what should appear for its inputs. Use a capitalized component name so JSX distinguishes it from an HTML element. Render it through JSX rather than invoking it as an ordinary utility.', 'function EventCard() { return <h2>Campus meetup</h2>; }', 'Which renders this component?', ['<EventCard />', '<eventcard />', 'EventCard = true'], 0, 'Capitalized JSX identifies your component rather than a native element name.'], ['Use JavaScript expressions inside JSX.', 'Curly braces insert an expression into JSX. Quoted attributes are literal strings. Keep complex calculations outside the markup when doing so makes the result easier to understand.', 'const count = 3;\nreturn <p>{count + 1} events</p>;', 'What text is shown?', ['count + 1 events', '4 events', '3 events'], 1, 'The expression is evaluated, then its result is rendered.'], ['Pass read-only inputs through props.', 'Props let a parent describe a child. Treat them as read-only: a child should request a change through a callback rather than mutating data owned by its parent.', 'function Card({ title }) { return <h2>{title}</h2>; }\n<Card title="SQL lab" />', 'What heading appears?', ['title', 'SQL lab', 'Card'], 1, 'The parent supplies the title prop used by the child.'], ['Compose an interface using children.', 'Composition combines small components without requiring a new component for every variation. The children prop carries nested content. A reusable panel can provide a frame while callers supply its contents.', 'function Panel({children}) { return <section>{children}</section>; }\n<Panel><p>Welcome</p></Panel>', 'What appears inside section?', ['A paragraph containing Welcome', 'Nothing', 'The word children'], 0, 'Nested JSX becomes the children prop.'], ['Render data as a list of elements.', 'Transform records into elements with map. Each item needs a key stable among its siblings. Prefer an ID from the record instead of creating a new random value during rendering.', 'events.map(event => <li key={event.id}>{event.name}</li>)', 'Which field is a good key?', ['A fresh random number', 'A stable unique event ID', 'The current filter text'], 1, 'Stable identity lets React match list items across updates.'], ['Keep list identity stable when order changes.', 'An index can describe position without describing identity. In an editable or reordered list, index keys can attach component state to the wrong record. Use a persistent record ID instead.', '[{id:"a"},{id:"b"}].map(item => <Row key={item.id} />)', 'Why prefer item.id here?', ['It is longer', 'It follows the record when the list changes', 'It prevents all rerenders'], 1, 'Record identity remains stable when positions change. It does not prevent all rendering.'], ['Respond to a click with a handler.', 'Pass a function to onClick. A handler can read props and request state changes when the event occurs. Calling the handler during render performs the action too early.', '<button onClick={() => register(event.id)}>Join</button>', 'When is register invoked?', ['On click', 'During every render', 'Only on server startup'], 0, 'The callback defers registration until the interaction.'], ['Use state for information that changes the screen.', 'A state update asks React to render using a new value. Changing a normal local variable does not preserve it across renders or request a render. Keep state as small as possible and derive the rest.', 'const [saved, setSaved] = useState(false);\n<button onClick={() => setSaved(true)}>{saved ? "Saved" : "Save"}</button>', 'What changes after a click?', ['The button text becomes Saved', 'The state variable is reassigned directly', 'Nothing can change'], 0, 'The setter requests a render with saved equal to true.'], ['Update an object without mutating existing state.', 'State snapshots should be treated as immutable. Create a new object while preserving fields that did not change. Mutating the old object can make updates difficult to detect and reason about.', 'setProfile(previous => ({...previous, year: 3}));', 'What does the spread preserve?', ['Existing profile fields', 'Only the year field', 'No fields'], 0, 'The previous fields are copied and year is then replaced.'], ['Keep controlled form inputs consistent.', 'A controlled input takes its displayed value from state and updates that state in onChange. An input that has value but no update handler may appear impossible to edit. Validate again on the server.', '<input value={name} onChange={e => setName(e.target.value)} />', 'Where is the displayed name stored?', ['Only in a CSS rule', 'In React state', 'In an HTML comment'], 1, 'The value prop reflects state, and onChange updates that state.'], ['Lift shared state to a common owner.', 'Two components that coordinate a selection need one shared source of truth. Move the selection to their closest appropriate common parent and pass its value and an update callback down.', 'Parent owns selectedEvent\nList selects → Parent updates → Detail displays', 'What avoids two conflicting selections?', ['A separate state copy in each child', 'One shared state owner', 'Disabling all interaction'], 1, 'Both children receive the same current selection from their parent.'], ['Represent loading separately from an empty result.', 'A loading request has not yet produced an answer. An empty successful result is an answer. Displaying both as an empty list can make the interface look broken. Distinguish loading, success and error.', 'if (loading) return <p role="status">Loading…</p>;\nif (error) return <p role="alert">Try again</p>;', 'When should an empty-state message appear?', ['After a successful empty result', 'Before every request finishes', 'Only after an error'], 0, 'An empty state should describe a known successful result with no items.'], ['Give an empty collection a useful next action.', 'An empty list can mean no records exist or that filters removed all matches. Explain the reason you know and offer an action such as clearing filters. Avoid implying data has loaded when it has not.', 'const visible = events.filter(matchesFilter);\nif (!visible.length) return <button onClick={clearFilters}>Clear filters</button>;', 'What action is useful for an empty filtered view?', ['Clear or adjust the filter', 'Delete the database', 'Show a fake record'], 0, 'The learner can recover without seeing invented results.'], ['Derive data rather than storing duplicate state.', 'If a displayed value can be calculated from existing props or state, calculate it during rendering. Duplicate state introduces extra synchronization work and can drift when one update path is missed.', 'const completed = tasks.filter(t => t.done).length;', 'Should completed usually be separate state?', ['Yes, every calculation needs state', 'No, derive it from tasks', 'Only if it is a number'], 1, 'The count is a direct derivation of the current tasks.'], ['Design a reusable input with an accessible label.', 'A reusable input should preserve ordinary input behavior and connect its label with an ID. Pass through useful attributes such as required and disabled. Placeholders supplement labels rather than replace them.', '<label htmlFor="email">Email</label>\n<input id="email" type="email" required />', 'What connects this label to the input?', ['Matching htmlFor and id', 'Matching CSS colors', 'The placeholder'], 0, 'The explicit association supports focus and accessible naming.'], ['Use effects to synchronize with an external system.', 'An effect is appropriate for connecting to an external subscription, not for deriving a value from current state. Clean up subscriptions so a changed dependency does not leave old work active.', 'useEffect(() => {\n const stream = subscribe(topic);\n return () => stream.close();\n}, [topic]);', 'Why return a cleanup function?', ['To close the old subscription', 'To render a heading', 'To change props directly'], 0, 'Cleanup releases the external resource before replacement or unmount.'], ['Handle a fetch result without accepting stale responses.', 'An older request can complete after a newer one. Cancel obsolete work or ignore a result whose request identity is no longer current. Check the response status before treating the body as success.', 'useEffect(() => {\n const controller = new AbortController();\n loadEvents(filter, controller.signal);\n return () => controller.abort();\n}, [filter]);', 'What can cancellation help prevent?', ['An obsolete request updating the view', 'All network failures', 'The need for error handling'], 0, 'Cancellation reduces stale work; failures still need an explicit error state.'], ['Offer recovery from a failed request.', 'A failed action should preserve the user input and describe the next useful step. Prevent accidental duplicate submissions while a request is pending. A retry should not invent a successful server result.', 'try { await saveDraft(text); }\ncatch { setError("Could not save. Your text is still here."); }', 'What should be preserved on failure?', ['The learner’s entered text', 'Only an error number', 'A fabricated success state'], 0, 'Preserving work allows recovery without repeating the entire task.'], ['Extract shared stateful behavior into a hook.', 'A custom hook groups reusable stateful logic. Hook calls belong at the top level of a component or another hook, so their order stays consistent. A hook does not automatically share state between callers.', 'function useToggle(initial=false) {\n const [on,setOn] = useState(initial);\n return [on, () => setOn(value => !value)];\n}', 'Do two callers automatically share one toggle?', ['Yes', 'No, each call has its own state', 'Only if both are buttons'], 1, 'Custom hooks share logic; each component invocation has its own state.'], ['Make an action operable with the keyboard.', 'Use native buttons for actions and links for navigation. Native controls provide expected keyboard behavior. A clickable div requires additional semantics and interaction logic that a button already supplies.', '<button type="button" onClick={openLesson}>Open lesson</button>', 'Which is the strongest default for an action?', ['An unlabelled clickable div', 'A native button with a clear name', 'A decorative image'], 1, 'A native button supports focus and keyboard activation.'], ['Test what a user can observe.', 'An interaction test should perform the action and assert a meaningful outcome. Checking that a handler function exists does not establish that the interface saves or displays the correct result.', 'Click Save → mock successful response → expect Saved label', 'Which assertion checks user-visible behavior?', ['The component file contains setState', 'The saved result appears after the click', 'The handler name is short'], 1, 'The outcome tests the behavior users depend on.'], ['Use available space without hiding essential actions.', 'Small screens need content that reflows and controls that remain reachable. Test long labels, zoom, keyboard focus and an on-screen keyboard. Avoid fixed widths that force the entire page to scroll sideways.', '.cards { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,18rem),1fr)); }', 'What should remain usable on a narrow screen?', ['The primary action and its label', 'Only the decorative hero', 'Only the sidebar'], 0, 'Essential tasks must remain reachable as the layout reflows.'], ['Ship a complete interaction, including failure and recovery.', 'A usable interface includes loading, empty, error and saved states. Verify the built version and the deployed configuration as well as the development screen. Keep rollback and a clear next action available.', 'Open → edit → save → refresh → confirm persisted data', 'Which check establishes persistence?', ['Only seeing the initial form', 'Refreshing and seeing the saved data', 'Changing the button color'], 1, 'Reloading verifies that the result was stored beyond component state.']],
  sql: [['Identify the grain of a table.', 'A table represents one kind of record at a chosen grain: for example, one registration per student and event. Establish that grain before counting or joining, or an apparently correct query may duplicate business facts.', 'registrations(id, student_id, event_id)', 'What does one registration row represent?', ['One specific student-event registration', 'Every registration in the college', 'A column name'], 0, 'The row grain is one registration, not the entire dataset.'], ['Select only the columns a result needs.', 'SELECT determines the output columns and FROM identifies the input relation. Prefer an explicit column list for an application contract, so an added source column does not silently change the response.', 'SELECT name, location FROM events;', 'Which columns are returned?', ['Every column', 'name and location', 'Only location'], 1, 'The projection explicitly names these two columns.'], ['Filter rows before later operations.', 'WHERE retains rows that satisfy its predicate. Use comparisons suited to the stored type and combine conditions deliberately. A row that fails the predicate is excluded from subsequent grouping.', 'SELECT name FROM events WHERE category = \'Workshop\';', 'Which rows remain?', ['All events', 'Only Workshop events', 'Only events with a missing category'], 1, 'The equality predicate retains rows whose category matches Workshop.'], ['Make row ordering explicit.', 'SQL does not promise a presentation order without ORDER BY. Include a stable secondary key when the main sort value can tie, especially when showing pages of results.', 'SELECT id, name FROM events ORDER BY starts_at, id;', 'Why include id after starts_at?', ['To break ties predictably', 'To remove duplicates', 'To count events'], 0, 'A unique secondary key makes ordering deterministic for equal timestamps.'], ['Handle NULL with the correct predicate.', 'NULL represents an unknown or absent value. Ordinary equality with NULL does not evaluate to true. Use IS NULL or IS NOT NULL and decide how absent values should affect your result.', 'SELECT id FROM students WHERE mentor_id IS NULL;', 'Which students match?', ['Students without a mentor value', 'Every student', 'Only mentor ID zero'], 0, 'IS NULL tests absence; zero is a distinct value.'], ['Choose the right count.', 'COUNT(*) counts rows. COUNT(column) counts rows whose chosen column is not NULL. This distinction matters after a left join, where an unmatched row contains NULLs for the right-side columns.', '-- three rows: mentor_id = 1, NULL, 2\nSELECT COUNT(*), COUNT(mentor_id) FROM students;', 'What pair is returned?', ['3, 3', '3, 2', '2, 3'], 1, 'There are three rows but only two non-NULL mentor values.'], ['Aggregate at an intentional grouping level.', 'GROUP BY collects rows with equal grouping values before aggregate functions are evaluated. Select grouped columns or aggregates so each output row has a clear meaning.', 'SELECT event_id, COUNT(*) AS registrations\nFROM registrations GROUP BY event_id;', 'What does each output row describe?', ['One event and its registration count', 'One student name', 'One database column'], 0, 'Grouping by event_id produces an aggregate per event.'], ['Filter groups with HAVING.', 'WHERE filters individual input rows; HAVING filters aggregate groups. Use HAVING when the condition depends on a count or sum calculated for a group.', 'SELECT event_id, COUNT(*) AS total\nFROM registrations GROUP BY event_id HAVING COUNT(*) >= 10;', 'Which events are returned?', ['Events with at least ten registrations', 'The first ten registrations', 'Events with exactly one registration'], 0, 'The aggregate predicate is evaluated on each event group.'], ['Give derived fields meaningful output names.', 'Aliases name expressions in the result. A clear alias forms a useful contract with a client and makes a derived metric understandable. It does not rename the original stored column.', 'SELECT amount_cents / 100.0 AS amount_rupees FROM payments;', 'What does AS do here?', ['Renames the output expression', 'Changes the stored table schema', 'Adds a new payment'], 0, 'The query result gets the alias; the source table is unchanged.'], ['Join on a relationship rather than coincidental text.', 'An inner join returns matching combinations of rows. Use the actual relationship key, and check whether it is one-to-one or one-to-many before summing values from either side.', 'SELECT r.id, e.name FROM registrations r\nJOIN events e ON e.id = r.event_id;', 'Which relationship connects these tables?', ['e.id = r.event_id', 'e.name = r.id', 'Every row matches every row'], 0, 'The registration stores the referenced event ID.'], ['Preserve unmatched rows with LEFT JOIN.', 'A left join keeps every row from its left input. Missing matches produce NULL right-side fields. A WHERE filter that requires a right-side value may remove those preserved rows.', 'SELECT e.id, r.id FROM events e\nLEFT JOIN registrations r ON r.event_id = e.id;', 'What happens to an event with no registrations?', ['It remains, with NULL r.id', 'It is always removed', 'A fake registration is created'], 0, 'The left-side event is preserved without inventing a registration.'], ['Use keys to identify rows reliably.', 'A primary key uniquely identifies a row and cannot be NULL. A useful key stays stable as ordinary descriptive fields change. A name is often a poor key because names can repeat or change.', 'CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT);', 'Which field identifies a student row?', ['name must always be unique', 'id', 'The row display order'], 1, 'The primary key provides the row identity.'], ['Represent relationships with foreign keys.', 'A foreign key describes a reference to a key in another table. With enforcement enabled, it prevents references to nonexistent records. Define the intended delete/update behavior explicitly.', 'registrations.event_id → events.id', 'What should a foreign-key constraint prevent?', ['A reference to an event that does not exist', 'Two students having the same name', 'Sorting an event list'], 0, 'Referential integrity protects the relationship between stored records.'], ['Model repeated relationships in their own table.', 'A student can attend many events and an event can have many students. A junction table represents each pairing. A unique pair constraint can prevent duplicate registration without restricting other events.', 'CREATE TABLE registrations (student_id INT, event_id INT,\n UNIQUE(student_id, event_id));', 'What does the unique pair prevent?', ['A student joining two different events', 'Duplicate registration for the same student and event', 'An event having many students'], 1, 'Only the identical pairing is restricted.'], ['Use a subquery to express a set condition.', 'EXISTS asks whether a subquery returns at least one row. NOT EXISTS can express absence without the NULL surprises of some NOT IN queries. Correlate the subquery to the intended outer record.', 'SELECT e.id FROM events e WHERE NOT EXISTS (\n SELECT 1 FROM registrations r WHERE r.event_id = e.id\n);', 'Which events are returned?', ['Events with no registrations', 'Events with exactly one registration', 'All registrations'], 0, 'The condition succeeds only when no matching registration exists.'], ['Validate analysis against edge cases.', 'Before trusting a query, test empty inputs, duplicate child rows, NULL values and ties. State the output grain and sort order, then check that joins have not multiplied a sum. Explain assumptions alongside the result.', 'Payment 1 = 1000 cents\nRefunds = 100 and 200 cents\nNet = 1000 - (100 + 200)', 'What is the correct net amount?', ['1700 cents', '700 cents', '2000 cents'], 1, 'Aggregate both refunds once and subtract them from one captured payment.']],
  dsa: [['Turn a problem into concrete inputs and outputs.', 'Before choosing an algorithm, work through the smallest useful example by hand. State assumptions such as whether duplicates are allowed and whether order matters. This exposes ambiguity before it becomes a bug.', 'Input: [2, 7], target 9\nOutput indices: [0, 1]', 'Which question clarifies a two-sum contract?', ['Can the same element be used twice?', 'What color is the editor?', 'Which company logo is shown?'], 0, 'Element reuse changes the valid solution and must be clarified.'], ['Compare growth rates rather than machine-specific timings.', 'Time complexity describes how work grows with input size. A loop that visits each element once performs linear work. Actual speed also depends on constants and the environment, so complexity is not a stopwatch reading.', 'for (const item of values) inspect(item);', 'What is the growth for one constant-time inspection per item?', ['O(1)', 'O(n)', 'O(n squared)'], 1, 'Doubling the input roughly doubles the number of inspections.'], ['Track array indices at the boundaries.', 'An array stores an ordered sequence. Empty arrays have no valid first element. When iterating, use a boundary that excludes length and test both an empty input and a one-element input.', 'const values = [4, 8, 12];\nfor (let i=0; i<values.length; i++) visit(values[i]);', 'What is the final valid index?', ['3', '2', '1'], 1, 'For three elements indexed from zero, the last index is two.'], ['Use a map to remember information already seen.', 'A map can associate a value with a previously seen position or count. In two sum, look for the needed complement before storing the current value so one element is not reused accidentally.', 'for (let i=0;i<nums.length;i++){\n const needed=target-nums[i];\n if(seen.has(needed)) return [seen.get(needed),i];\n seen.set(nums[i],i);\n}', 'Why look up before inserting the current element?', ['To prevent using the same index twice', 'To sort the array', 'To remove all duplicates'], 0, 'The map then contains only earlier positions.'], ['Move two pointers using a justified invariant.', 'For a sorted array, a pair sum that is too small can be increased by moving the left pointer right. A sum that is too large can be decreased by moving the right pointer left. Sorting is a required assumption for this reasoning.', 'values=[1,3,5,8], target=9\nleft=0, right=3 → sum=9', 'Which assumption supports these pointer moves?', ['The input is sorted', 'Every value is positive', 'The array has no duplicates'], 0, 'Monotonic order makes the direction of each move meaningful.'], ['Maintain a window instead of recomputing overlapping work.', 'A sliding window reuses information from neighboring ranges. For a fixed-length sum, subtract the outgoing value and add the incoming value. Variable-size windows require a condition that justifies moving the left boundary.', 'values=[2,3,4,5], k=2\nfirst sum=5\nnext sum=5-2+4=7', 'What is the final two-item window sum?', ['7', '9', '14'], 1, 'Moving once more gives 7-3+5, which is 9.'], ['Track repeated characters with positions or counts.', 'A longest-unique-substring window must exclude all repeated characters within its current boundaries. When moving the left boundary, never move it backward to an older occurrence outside the window.', 'text="abba"\nleft=Math.max(left,lastSeen.get(char)+1);', 'Why use Math.max?', ['To prevent the left boundary moving backward', 'To count every character twice', 'To sort the letters'], 0, 'An old occurrence outside the current window must not expand it backward.'], ['Use a stack for nested or last-in-first-out work.', 'A stack removes the most recently added item first. Matching brackets need the latest unmatched opening bracket. An empty-stack close or a mismatched type is a failure even when the total number of brackets is even.', 'Input: "([)]"\nStack before ): ["(", "["]', 'Is this bracket sequence valid?', ['Yes, counts match', 'No, nesting is incorrect', 'Only if spaces are removed'], 1, 'The closing parenthesis does not match the latest opening bracket.'], ['Use a queue for first-in-first-out processing.', 'A queue processes items in arrival order. In an array-backed queue, a head index can avoid repeatedly shifting every remaining item. Decide when to compact or replace old storage for long-lived queues.', 'queue=["A","B","C"]; head=0;\nconst next=queue[head++];', 'Which item is processed first?', ['C', 'B', 'A'], 2, 'The head initially points at the first arrived item.'], ['Preserve a binary-search interval invariant.', 'Binary search discards a portion of a sorted search space after each comparison. Be consistent about inclusive or half-open bounds. Empty ranges and values at either end reveal off-by-one mistakes.', 'let low=0,high=values.length-1;\nwhile(low<=high){ const mid=Math.floor((low+high)/2); /* compare */ }', 'What allows discarding half the range?', ['Sorted order or a monotonic predicate', 'The array length being even', 'Using a recursive function'], 0, 'The comparison must imply which side can still contain the answer.'], ['Choose sorting with time, space and stability in mind.', 'Different sorting algorithms make different tradeoffs. Merge sort combines sorted halves and has O(n log n) time, while a straightforward implementation uses extra storage. Stability matters when preserving earlier order among equal keys.', '[{score:80,id:"a"},{score:80,id:"b"}]', 'What does a stable sort preserve for equal scores?', ['Their prior relative order', 'Only numeric IDs', 'Reverse alphabetical order'], 0, 'Equal-key records retain their order from before the sort.'], ['Write a base case that terminates recursion.', 'A recursive function needs a base case and progress toward it. The base case handles the simplest valid input. A recursive call with an unchanged input never gets closer to termination.', 'function factorial(n){\n if(n===0)return 1;\n return n*factorial(n-1);\n}', 'What is factorial(0)?', ['0', '1', 'undefined'], 1, 'The base case defines the empty product as one.'], ['Trace recursive calls and their returned values.', 'Calls descend toward a base case, then results return through earlier calls. Keep the call stack separate from the running expression. Test depth limits before using recursion for very large inputs.', 'function sum(n){return n===0?0:n+sum(n-1);}\nsum(3)', 'What result returns?', ['3', '6', '9'], 1, 'The returned expression is 3+2+1+0.'], ['Describe linked-list changes through references.', 'A linked list follows next references rather than contiguous array indices. Changing a node reference can disconnect the remaining list, so preserve the next node before replacing the link.', 'A → B → C\nconst next = current.next;', 'Why save current.next before changing it?', ['To retain access to the remaining nodes', 'To sort values automatically', 'To create an array index'], 0, 'The old next link may otherwise be lost after mutation.'], ['Reverse a list while keeping the unprocessed suffix reachable.', 'An iterative reversal maintains a reversed prefix and an unprocessed suffix. Save the next node, redirect the current link, then advance both pointers. The original head becomes the new tail.', 'const next=current.next;\ncurrent.next=previous;\nprevious=current;\ncurrent=next;', 'After processing the whole list, which pointer is the new head?', ['current', 'previous', 'The old head unchanged'], 1, 'previous points at the final processed node, now the head.'], ['Recognize tree structure and empty children.', 'A tree connects nodes without cycles through parent-child relationships. A binary tree has at most two children per node. Many algorithms need an explicit empty-node case to handle leaves and an empty tree.', 'function height(node){\n if(!node)return 0;\n return 1+Math.max(height(node.left),height(node.right));\n}', 'What height does this convention give an empty tree?', ['0', '1', '-1 always'], 0, 'The function explicitly returns zero for an absent node.'], ['Use depth-first traversal to explore a branch.', 'Depth-first search explores descendants before returning to alternatives. Preorder visits a node before its children; postorder visits it afterward. Choose the order based on which information the calculation needs.', 'visit(node);\ndfs(node.left);\ndfs(node.right);', 'Which traversal order is shown?', ['Postorder', 'Preorder', 'Level order'], 1, 'The current node is visited before either subtree.'], ['Use breadth-first traversal to process levels.', 'Breadth-first search keeps a queue of discovered nodes. Processing the current queue length groups one tree level at a time. In an unweighted graph, BFS can find the fewest-edge path.', 'queue=[root];\nwhile(head<queue.length){const node=queue[head++]; /* add children */}', 'Which structure supports this traversal?', ['A first-in-first-out queue', 'Only a recursive call stack', 'A sorted set of labels'], 0, 'The queue processes earlier discoveries before their descendants.'], ['Use binary-search-tree ordering carefully.', 'A binary search tree defines ordering between a node and all values in its subtrees. Checking only each node against its immediate children can miss an invalid deeper descendant. Carry lower and upper bounds.', 'Root 10\nLeft child 5 with right descendant 12', 'Is this a valid BST with distinct keys?', ['Yes, 12 is greater than 5', 'No, 12 is in the left subtree of 10', 'Only if the tree is balanced'], 1, 'All values in the left subtree must be less than 10.'], ['Distinguish a heap property from a fully sorted sequence.', 'A min-heap keeps its smallest item at the root, but siblings and deeper levels need not be fully sorted. Inserting or removing the root restores a local structural invariant rather than sorting every element.', 'Min-heap values: [1,4,2,7,5]', 'Which item is available at the root?', ['The median', 'The minimum', 'The maximum'], 1, 'The min-heap invariant guarantees the smallest root.'], ['Represent graph edges and direction explicitly.', 'An adjacency list stores each node’s neighbors. Directed edges and undirected edges need different insertion rules. Include isolated nodes and decide whether multiple edges are meaningful for the problem.', 'const graph={A:["B"],B:[]};', 'Does this representation imply an edge B → A?', ['Yes', 'No', 'Only when labels are uppercase'], 1, 'The listed directed edge goes from A to B only.'], ['Mark visited nodes to avoid repeated graph work.', 'Graphs can contain cycles and several paths to a node. Record visited status when discovering a node so it is not queued repeatedly. For reachability, each vertex should need processing only once.', 'A → B → C → A', 'What prevents endless traversal?', ['A visited set', 'Sorting node names', 'A larger queue'], 0, 'Visited status stops revisiting the same cycle indefinitely.'], ['Recognize overlapping subproblems.', 'Dynamic programming helps when smaller subproblems repeat and their results can be reused. Define the state and recurrence before choosing storage. A fast cache for the wrong state still produces the wrong answer.', 'fib(n)=fib(n-1)+fib(n-2)', 'What work repeats in a naive recursion?', ['Computations for the same smaller n', 'Only input parsing', 'No work ever repeats'], 0, 'Many branches request the same Fibonacci subproblems.'], ['Memoize by every input that determines a result.', 'Memoization caches results of recursive subproblems. The key must include all relevant state, and the cached value must be reused before recomputing. Caching only an index can be wrong when remaining capacity also matters.', 'solve(index, remainingCapacity)', 'Which cache key is sufficient in general?', ['index only', 'remainingCapacity only', 'Both index and remainingCapacity'], 2, 'Different capacities at the same index may have different optimal results.'], ['Build a table in dependency order.', 'Bottom-up DP evaluates smaller states before the states that depend on them. Set base cases explicitly. If only a few previous states are needed, storage can sometimes be reduced after the recurrence is correct.', 'dp[0]=0; dp[1]=1;\nfor(let i=2;i<=n;i++)dp[i]=dp[i-1]+dp[i-2];', 'Why compute increasing i?', ['The required earlier states are already available', 'It makes every algorithm greedy', 'It removes the base cases'], 0, 'Each recurrence depends on two smaller indices.'], ['Choose a state with enough information for future choices.', 'A DP state summarizes the past information that can affect later decisions. Too little information merges different situations; too much information can make the state space impractical. Explain what each coordinate means.', 'knapsack(i, capacity)', 'What does capacity represent?', ['Remaining resource available for future choices', 'The total number of function calls', 'A sort position'], 0, 'The remaining resource constrains which later choices are feasible.'], ['Justify a greedy choice instead of assuming it works.', 'A greedy algorithm commits to a locally preferred choice. It needs a reason that this choice can belong to an optimal solution. A counterexample is valuable: one small failure disproves a universal rule.', 'Coins [1,3,4], amount 6\nLargest-first picks 4+1+1', 'What shows largest-first is not optimal here?', ['3+3 uses fewer coins', '4 is the largest coin', '6 is positive'], 0, 'The alternative uses two coins instead of three.'], ['Undo a choice during backtracking.', 'Backtracking explores a choice, processes its consequences, then restores the previous state before trying a sibling. Missing the undo step leaks one branch’s decisions into another.', 'path.push(choice);\nsearch();\npath.pop();', 'Why call pop after search?', ['To restore the state for the next branch', 'To sort the path', 'To remove every possible solution'], 0, 'Each branch should start from the same prior path.'], ['Explain tradeoffs with constraints and evidence.', 'An interview answer should describe correctness, time, memory and the relevant input constraints. A faster asymptotic approach may need more space or stronger assumptions. Use a concrete example to explain the choice.', 'Two-sum: nested loops versus a hash map', 'What tradeoff does the usual hash-map approach make?', ['Extra memory for fewer repeated searches', 'No memory and no work', 'Sorted output automatically'], 0, 'A map stores prior values to reduce repeated scanning.'], ['Select a pattern from the structure of the problem.', 'Do not force every question into the last pattern you learned. Look for ordered search spaces, nested relationships, contiguous ranges, repeated states or graph connections. Validate the chosen invariant with edge cases.', 'Find the shortest path by number of edges in an unweighted graph.', 'Which pattern is a strong starting point?', ['Breadth-first search', 'Largest-first coin selection', 'Sorting by vertex name'], 0, 'BFS explores paths in increasing edge count in an unweighted graph.']],
  python: [['Run a small expression and inspect its result.', 'Python statements are executed in order. A string literal preserves its text, while an expression can calculate a value. Use print to inspect a small experiment before building a larger script.', 'print("Hello, campus")\nprint(2 + 3)', 'What does the second line print?', ['23', '5', '2 + 3'], 1, 'The numeric expression adds two and three before printing.'], ['Use names to keep meaningful values.', 'A variable name is bound to a value. Rebinding a name changes what that name refers to; it does not rename every other value. Choose names that explain the role of the data.', 'score = 40\nscore = score + 10', 'What is score now?', ['40', '10', '50'], 2, 'The new binding uses the earlier score to calculate fifty.'], ['Distinguish text operations from numeric operations.', 'Strings represent text and support operations such as concatenation and slicing. Convert text to a number before numerical arithmetic, and handle invalid input explicitly. Identifiers with leading zeros should often stay strings.', 'student_id = "0042"\nlabel = "ID: " + student_id', 'What is label?', ['ID: 42', 'ID: 0042', '46'], 1, 'Concatenation preserves the stored text, including its leading zeros.'], ['Use indentation to express conditional branches.', 'Python uses indentation to group a branch’s statements. Test boundary values and make the else behavior clear. Avoid treating a missing value as equivalent to zero when that difference matters.', 'score = 50\nif score >= 50:\n    result = "pass"\nelse:\n    result = "retry"', 'What is result?', ['pass', 'retry', 'None'], 0, 'The inclusive comparison accepts the boundary score.'], ['Trace a for loop over a predictable sequence.', 'A for loop visits values from an iterable. range stops before its upper bound. When counting or summing, inspect the exact generated values rather than assuming the endpoint is included.', 'total = 0\nfor n in range(1, 4):\n    total += n', 'What is total?', ['10', '6', '4'], 1, 'The loop visits one, two and three.'], ['Return results from a function.', 'A function can accept inputs and return a result for other code to use. Printing a value is different from returning it. A function without an explicit return produces None.', 'def square(n):\n    return n * n\nvalue = square(4)', 'What is value?', ['8', '16', 'None'], 1, 'The function returns four multiplied by four.'], ['Modify and copy lists deliberately.', 'Lists are ordered, mutable sequences. Assigning one list to another name does not copy it. Use a copy when later mutations should not affect the original list.', 'a = [1, 2]\nb = a\nb.append(3)', 'What is a?', ['[1, 2]', '[1, 2, 3]', '[3]'], 1, 'Both names refer to the same mutable list.'], ['Use dictionary keys for lookup.', 'A dictionary associates keys with values. Indexing an absent key raises KeyError; get can return a specified fallback. A fallback should represent a sensible domain rule rather than hiding malformed data.', 'counts = {"SQL": 3}\nvalue = counts.get("DSA", 0)', 'What is value?', ['3', '0', 'KeyError'], 1, 'The missing key uses the explicitly provided fallback zero.'], ['Use tuples for a fixed grouping of values.', 'Tuples are ordered and immutable containers. Unpacking assigns corresponding values to separate names. Immutability of the container does not freeze mutable objects stored inside it.', 'point = (3, 5)\nx, y = point', 'What is y?', ['3', '5', '(3, 5)'], 1, 'Unpacking maps the second tuple value to y.'], ['Use sets when membership and uniqueness matter.', 'A set stores unique elements and supports membership checks. Do not rely on its iteration order for a presentation contract. Sort the result when a deterministic display order is required.', 'topics = {"SQL", "DSA", "SQL"}', 'How many elements are stored?', ['3', '2', '1'], 1, 'The duplicate SQL value appears only once.'], ['Close files using a context manager.', 'A with statement releases the file when the block exits, including on an exception. Specify encoding for predictable text handling. Keep a file path separate from the text you expect to read.', 'with open("notes.txt", encoding="utf-8") as handle:\n    notes = handle.read()', 'When is the handle closed?', ['When the with block exits', 'Only when the computer restarts', 'Never'], 0, 'The context manager closes its resource automatically.'], ['Catch a specific expected file error.', 'Handle errors where you can provide useful recovery. Catching FileNotFoundError can offer a missing-file message while leaving unrelated programming errors visible. Avoid a broad exception handler that quietly discards every failure.', 'try:\n    open("missing.csv")\nexcept FileNotFoundError:\n    message = "Choose a file"', 'Which error is handled specifically?', ['A missing file', 'Every possible error', 'Only syntax errors'], 0, 'The handler names FileNotFoundError rather than a broad catch-all.'], ['Transform a collection with a readable comprehension.', 'A list comprehension combines iteration, an optional filter and an output expression. Keep complicated branching in a named function. Predict the selected input values before calculating their transformed output.', 'values = [n * n for n in range(5) if n % 2 == 0]', 'What is values?', ['[0, 4, 16]', '[0, 1, 4, 9, 16]', '[2, 4]'], 0, 'The even inputs zero, two and four are squared.'], ['Import functionality from an explicit module.', 'Modules organize reusable code. An import makes the selected names available in your script. Avoid giving your own file the same name as a standard module you want to import.', 'import math\nvalue = math.sqrt(81)', 'What is value numerically?', ['9', '81', '6561'], 0, 'sqrt computes the square root of eighty-one.'], ['Keep instance data on the instance.', 'A class packages related state and behavior. The self parameter refers to the instance. Initialize per-instance mutable data inside the initializer so separate objects do not accidentally share one list.', 'class Student:\n    def __init__(self, name):\n        self.name = name\n        self.notes = []', 'Why initialize notes here?', ['Each student gets a separate list', 'It creates one shared list for everyone', 'It disables append'], 0, 'The initializer runs for each new instance.'], ['Read CSV data using a parser rather than splitting commas.', 'Quoted CSV fields can contain commas and newlines. Use the csv module so quoting rules are interpreted correctly. DictReader uses the header to name fields, while values initially remain text.', 'import csv\nwith open("scores.csv", newline="", encoding="utf-8") as handle:\n    rows = list(csv.DictReader(handle))', 'What is a score value initially?', ['Usually text from the CSV field', 'Always an integer', 'Always a Python class'], 0, 'A text parser does not infer every domain type; convert and validate explicitly.'], ['Distinguish absent measurements from zero.', 'A missing measurement is different from a measured zero. Inspect where missing values occur and decide a documented handling rule. Filling everything with zero can distort summaries and hide data-quality problems.', 'values = [10, None, 0]\nknown = [v for v in values if v is not None]', 'What is known?', ['[10]', '[10, 0]', '[10, None, 0]'], 1, 'The valid zero is retained while the absent value is excluded.'], ['Define an analysis question before calculating.', 'A useful analysis begins with a decision and a measurable question. Define the population, period, unit and missing-data rule. Looking only for an attractive chart can conceal an unclear or misleading metric.', 'Question: What fraction of enrolled students submitted by the deadline?', 'Which denominator fits this question?', ['All enrolled eligible students', 'Only students who submitted', 'All website page views'], 0, 'The denominator must represent the population in the stated question.'], ['Convert and validate a column before aggregation.', 'Imported numeric-looking text should be converted before a sum. Decide how to report invalid values rather than silently combining them. Preserve the original input when auditability matters.', 'raw = ["10", "20", "30"]\namounts = [int(value) for value in raw]', 'What is sum(amounts)?', ['102030', '60', '3'], 1, 'Explicit integer conversion permits numeric addition.'], ['Choose a chart that matches the relationship.', 'Use a line chart for an ordered time series and a bar chart for category comparisons. Label the unit, time range and source. A chart should reveal the relevant comparison without hiding missing periods or changing scales.', 'Weekly completed tasks: [3, 5, 4, 7]', 'Which display naturally shows this weekly trend?', ['A line chart with labelled weeks', 'An unlabelled random scatter', 'A single decorative icon'], 0, 'Ordered time points support a labelled line chart.'], ['Separate an observation from an explanation.', 'A dataset can show a relationship without establishing its cause. Explain the observed result, checks performed, alternative explanations and limitations. Do not turn a correlation into a causal conclusion without an appropriate design.', 'Students attending a workshop submitted more projects.', 'Which conclusion is supported by this observation alone?', ['The workshop definitely caused every improvement', 'Attendance and submissions were associated in this sample', 'Workshops guarantee employment'], 1, 'Other differences between attendees and nonattendees may explain the association.'], ['Package an investigation so someone else can reproduce it.', 'A useful analysis repository includes input provenance, transformation steps, environment instructions and a clear result. Keep private data and credentials out of the repository. Separate raw inputs from generated outputs.', 'README + source script + dependencies + data source notes', 'What most helps another learner reproduce the result?', ['Documented inputs and execution steps', 'Only a screenshot', 'Only an unlabelled chart'], 0, 'Reproduction requires knowing what data and code produced the result.']],
  devops: [['Map a delivery process from source to recovery.', 'Delivery includes preparing code, checking it, building an artifact, releasing it, observing behavior and recovering when necessary. A successful build does not prove the running service is healthy. Define a release check and a rollback path.', 'commit → checks → artifact → deploy → health → observe', 'What should follow deployment?', ['A health and behavior check', 'Deleting every previous artifact', 'Assuming success because the build passed'], 0, 'A running service must be checked in its actual environment.'], ['Inspect a Git change before recording it.', 'Use status and diff to understand exactly what changed. Stage only the intended files and inspect staged changes before committing. Keep generated output, local databases and secrets out of version control.', 'git status --short\ngit diff\ngit diff --staged', 'Which command shows staged content?', ['git diff --staged', 'git status --ignored only', 'git branch --all'], 0, 'The staged diff shows what will enter the next commit.'], ['Identify a process, address and listening port.', 'A service listens on an address and port. Binding loopback restricts direct access to the local machine; a reverse proxy can forward traffic to it. A connection refusal can mean the process is not listening at the expected location.', 'API listens on 127.0.0.1:5080\nProxy forwards the public HTTPS origin', 'What does loopback binding mean?', ['The service is directly reachable only locally', 'The service has no port', 'Every computer can directly connect to it'], 0, 'The loopback interface is local to the machine.'], ['Design a health check with a meaningful scope.', 'A process being alive differs from its readiness to serve requests. A useful readiness check verifies critical dependencies without exposing credentials or private records. Keep checks bounded so the health endpoint does not become a heavy workload.', 'GET /health → {status:"ready",database:"ok"}', 'What should a readiness check avoid exposing?', ['Private records and credentials', 'A bounded status signal', 'A success or failure status'], 0, 'Health information should support operations without disclosing sensitive data.'], ['Separate a container image from a running container.', 'An image is a packaged filesystem and configuration. A container is a running instance using an image. Writable container layers are not a reliable home for long-lived institutional records; use an intentional persistent storage location.', 'image → container process + writable runtime layer', 'Where should important persistent records live?', ['In planned persistent storage with backups', 'Only in a disposable container layer', 'Only in the browser console'], 0, 'Application replacement must not erase institutional records.'], ['Build repeatably from a declared dependency set.', 'A repeatable image uses an explicit runtime and a locked dependency install. Copy only necessary files and run with a limited user. Smaller build contexts reduce accidental inclusion of local secrets and data.', 'COPY package.json package-lock.json ./\nRUN npm ci\nCOPY server ./server', 'Why include the lockfile?', ['To make dependency resolution repeatable', 'To store API credentials', 'To disable all security updates permanently'], 0, 'The lockfile records the dependency versions and resolution used by the build.'], ['Separate environment configuration from source.', 'Different environments need different origins, storage locations and service endpoints. Validate required configuration at startup. A missing production setting should fail clearly rather than falling back to a working-looking demo environment.', 'APP_ORIGIN=https://college.example\nSTUDENTOS_DATA_DIR=/var/lib/studentos', 'What belongs in configuration?', ['The deployment origin and storage path', 'A student password printed in a page', 'An assumed production localhost URL'], 0, 'These values depend on the environment and should be validated there.'], ['Keep secrets out of shipped client assets.', 'A server secret belongs on the server. Anything compiled into browser JavaScript can be inspected by a user. An ignored local environment file reduces accidental commits but does not replace access control or rotation.', 'Server reads API_KEY\nBrowser calls your authenticated API', 'Where should a provider API key be used?', ['In server-side requests', 'In a public VITE_ variable', 'In a CSS custom property'], 0, 'The browser should not receive the provider credential.'], ['Automate checks that can stop a broken release.', 'A useful pipeline installs locked dependencies, runs meaningful tests and builds the deployable artifact. Restrict workflow permissions. A green pipeline reflects only what its tests assert, so add regression cases for real failures.', 'npm ci\nnpm test\nnpm run build', 'What makes a regression test useful?', ['It fails for the known bug and passes after the fix', 'It checks only that a filename exists', 'It always returns success'], 0, 'The test must protect the behavior that previously failed.'], ['Release a specific artifact with a recovery option.', 'Deploy an identifiable version and keep the prior artifact available. Check migrations for compatibility before changing traffic. A staged rollout can reduce the blast radius of a faulty change.', 'release-42 → smoke checks → traffic\nrelease-41 retained for recovery', 'What identifies a recoverable release?', ['A versioned artifact and compatible recovery procedure', 'An edited live file with no history', 'Only the current browser screenshot'], 0, 'Recovery depends on known code and data compatibility.'], ['Observe symptoms using logs, metrics and context.', 'Logs describe events; metrics show behavior over time. Request IDs help connect a reported failure with related events. Avoid logging passwords, raw session tokens or private request bodies. Alert on actionable user-impacting failures.', 'request_id=abc status=500 latency_ms=140', 'Which value helps trace one failed request?', ['The request ID', 'A saved plaintext password', 'A decorative application color'], 0, 'A correlation identifier connects relevant operational events without exposing credentials.'], ['Test recovery before depending on it.', 'A backup becomes useful when it can be restored and checked. Verify integrity and important record counts, then rehearse the application restart. Restoring into a new location preserves the current data while the restored copy is inspected.', 'backup → new restore location → integrity check → app verification', 'What best demonstrates a usable backup?', ['A successful restore and application verification', 'A file named backup with no checks', 'A screenshot of the backup button'], 0, 'Recovery must be exercised, not inferred from the existence of a file.']]
};
export const curriculum = {};
for (const [course, lessons] of Object.entries(rows)) {
  if (lessons.length !== lessonNames[course].length) throw new Error(`Curriculum length mismatch: ${course}`);
  curriculum[course] = lessons.map(([objective, reading, example, question, options, correct, explanation], index) => ({
    id: `${course}:${index}`,
    course,
    index,
    title: lessonNames[course][index],
    objective,
    reading,
    example,
    question,
    options,
    correct,
    explanation,
    sourceUrl: sources[course],
    minutes: 12 + index % 3 * 3,
    version: 1
  }));
}
for (const course of advancedTracks) curriculum[course.id] = advancedRows[course.id].map(([title, reading, example, question, options, correct, explanation], index) => ({
  id: course.id + ':' + index,
  course: course.id,
  index,
  title,
  objective: title,
  reading,
  example,
  question,
  options,
  correct,
  explanation,
  sourceUrl: course.sourceUrl,
  minutes: 18,
  version: 1
}));
export function getLesson(course, index) {
  return curriculum[course]?.[index];
}
export function publicLesson(course, index) {
  const lesson = getLesson(course, index);
  if (!lesson) return null;
  const {
    correct,
    explanation,
    ...publicFields
  } = lesson;
  return publicFields;
}
